import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.sc8Z_ZE3.js";const p=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/glossary.md","filePath":"concepts/glossary.md"}'),a={name:"concepts/glossary.md"};function d(n,t,i,c,h,l){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>The words this wiki uses, in one place.</p><table tabindex="0"><thead><tr><th>Word</th><th>Means</th></tr></thead><tbody><tr><td><strong>Octryx AI</strong></td><td>The platform this wiki documents: the layer above your coding agent. Octryx is the family of products it belongs to.</td></tr><tr><td><strong>Workspace</strong></td><td>Where a team works: its chats, work items, repositories, knowledge, rules, models and budget. See <a href="/docs/concepts/workspaces">Workspaces and roles</a>.</td></tr><tr><td><strong>Platform admin</strong></td><td>Administers the whole installation.</td></tr><tr><td><strong>Workspace admin, owner</strong></td><td>Administer one Workspace.</td></tr><tr><td><strong>Work item</strong></td><td>A bug, story, epic or task, from your tracker or created in Octryx AI.</td></tr><tr><td><strong>Workflow</strong></td><td>The phases, checks, loops and approvals for a kind of work. See <a href="/docs/concepts/workflows">Workflows and phases</a>.</td></tr><tr><td><strong>Run</strong></td><td>One workflow working on one work item, with its record. See <a href="/docs/concepts/runs">Runs and their record</a>.</td></tr><tr><td><strong>Phase</strong></td><td>One step of a run, for example reproduce, fix, pipeline or review.</td></tr><tr><td><strong>Phase brief</strong></td><td>The short instructions the agent gets at the start of a phase: what the platform enforces and what it does itself.</td></tr><tr><td><strong>Size class</strong></td><td>S, M or L: how much of a workflow a work item needs, chosen from its type, labels and components.</td></tr><tr><td><strong>Evidence</strong></td><td>What a run proves, kept on the run: red on the old code, the pipeline, the browser test, the review. See <a href="/docs/concepts/evidence">Evidence and checks</a>.</td></tr><tr><td><strong>Red on the old code</strong></td><td>The proof that a bug&#39;s test fails on the base commit and passes with the fix.</td></tr><tr><td><strong>Pipeline</strong></td><td>The repository&#39;s declared tests, run by the platform without the agent.</td></tr><tr><td><strong>Browser test</strong></td><td>Scenarios the platform writes and runs in a real browser against an app with a UI.</td></tr><tr><td><strong>Independent review</strong></td><td>A separate review of a change, without the author&#39;s history.</td></tr><tr><td><strong>Four-eyes approval</strong></td><td>An approval by a person other than the requester and the authors.</td></tr><tr><td><strong>Run memory</strong></td><td>What earlier runs learned about a repository; information, never a permission.</td></tr><tr><td><strong>Correction</strong></td><td>A person correcting an agent or the review bot; counted, and turned into a rule or a check when it repeats.</td></tr><tr><td><strong>Seat</strong></td><td>A person&#39;s own subscription (Claude, or ChatGPT for Codex), used for runs on their machine.</td></tr><tr><td><strong>Governed route</strong></td><td>Company models through the platform&#39;s gateway, billed to the Workspace&#39;s budget.</td></tr><tr><td><strong>Gateway</strong></td><td>The platform&#39;s model endpoint: policy, allow list, secret scan, transcript and cost for model calls.</td></tr><tr><td><strong>Device</strong></td><td>A developer&#39;s machine registered with <code>octryx-claude device enable</code>, which runs phases for the platform.</td></tr><tr><td><strong>Launcher</strong></td><td><code>octryx-claude</code> (short: <code>octryx</code>), which runs Claude Code or Codex under the Workspace&#39;s rules. See <a href="/docs/install/launcher">Launcher and devices</a>.</td></tr><tr><td><strong>Connection</strong></td><td>A link to one of your tools, such as Jira or a Git host. See <a href="/docs/connections/">Connections</a>.</td></tr><tr><td><strong>Data class</strong></td><td>A Workspace&#39;s classification, from Public to Secret, which decides what models and seats may see. See <a href="/docs/security/data-classes">Data classes</a>.</td></tr><tr><td><strong>Policy</strong></td><td>A rule written in Cedar that restricts what people and agents may do. See <a href="/docs/rules/policies">Policies and four-eyes</a>.</td></tr><tr><td><strong>Review bot</strong></td><td>Octryx AI&#39;s pull request reviewer. See <a href="/docs/review-bot/">Pull request review bot</a>.</td></tr><tr><td><strong>Status stages</strong></td><td>Planned, Building, Built, In real runs: how far each feature really is. See <a href="/docs/start/status">Status and results</a>.</td></tr></tbody></table>',3)])])}const u=e(a,[["render",d]]);export{p as __pageData,u as default};
